import { Group } from '@visx/group';
import { isUndefined } from 'lodash-es';
import React, { memo } from 'react';

import { MarkerRenderer } from './MarkerRenderer.js';
import { TestIds } from '../constants.js';
import { useAnnotationsSelectionState } from '../hooks/store/selectors.js';
import {
  useSetStateSelection,
  useSetStateTooltip,
} from '../hooks/store/state-setters.js';
import { useMarkersInteractions } from '../hooks/useMarkersInteractions.js';
import { initialState } from '../providers/AnnotationsDataInitialState.js';
import { AnnotationGroup } from '../types/annotations.js';

type MarkersGroupProps = {
  annotationsGroup: AnnotationGroup[];
  groupId: string;
  trackNumber: number;
};

export const MarkersGroup = memo(
  ({ annotationsGroup, groupId, trackNumber }: MarkersGroupProps) => {
    const updateTooltipState = useSetStateTooltip();
    const updateTooltipSelection = useSetStateSelection();
    const { pinnedGroup, hoveredGroup, hoveredTrack } =
      useAnnotationsSelectionState();
    const { onMarkersInteraction } = useMarkersInteractions();

    const isTooltipPinned = !isUndefined(pinnedGroup);

    const handleMouseMove = (event: React.TouchEvent | React.MouseEvent) => {
      if (isTooltipPinned) {
        return;
      }

      const { clientX, clientY } =
        'touches' in event ? event.touches[0] : event;

      updateTooltipState({ position: { x: clientX, y: clientY } });
    };

    const handleMouseEnter = (event: React.TouchEvent | React.MouseEvent) => {
      if (isTooltipPinned) {
        return;
      }

      const { clientX, clientY } =
        'touches' in event ? event.touches[0] : event;
      const newSelection = { hoveredGroup: groupId, data: annotationsGroup };

      updateTooltipState({
        position: { x: clientX, y: clientY },
        data: annotationsGroup,
        visibility: true,
      });

      updateTooltipSelection(newSelection);
      onMarkersInteraction?.(newSelection);
    };

    const handleMarkerHover = (itemId: string) => {
      const isHoveredGroup =
        hoveredGroup === groupId && hoveredTrack === trackNumber;

      if (isTooltipPinned || !isHoveredGroup) {
        return;
      }

      updateTooltipSelection({ hoveredItem: itemId });
    };

    const handleMouseClick = (event: React.TouchEvent | React.MouseEvent) => {
      event.stopPropagation();

      const { clientX, clientY } =
        'touches' in event ? event.touches[0] : event;
      const newSelection = {
        hoveredGroup: groupId,
        data: annotationsGroup,
        pinnedGroup: isTooltipPinned ? undefined : groupId, // if tooltip was already pinned, unpin
      };

      updateTooltipState({
        position: { x: clientX, y: clientY },
        data: annotationsGroup,
        visibility: true,
        pinned: !isTooltipPinned, // if tooltip was already pinned, show updated info but unpin
      });
      updateTooltipSelection(newSelection);
      onMarkersInteraction?.(newSelection);
    };

    const handleMouseLeave = () => {
      if (isTooltipPinned) {
        return;
      }

      updateTooltipState(initialState.tooltip);
      updateTooltipSelection(initialState.selection);
      onMarkersInteraction?.(initialState.selection);
    };

    return (
      <Group
        onMouseMove={handleMouseMove}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onClick={handleMouseClick}
        data-testid={`${TestIds.MarkerGroup}-${groupId}`}
      >
        {[...annotationsGroup] // this is needed because sort method mutates the original array, and affects the order of the tooltip items
          .sort((a, b) => a.priority - b.priority)
          .map(({ key, annotations }) => (
            <MarkerRenderer
              key={key}
              data={annotations}
              markerId={key}
              onMarkerHover={handleMarkerHover}
              trackNumber={trackNumber}
            />
          ))}
      </Group>
    );
  },
);

MarkersGroup['displayName'] = 'MarkersGroup';
